import { Component, Element, Event, EventEmitter, h, Host, Prop } from '@stencil/core';
import { getDefaultSlotContent, isDescriptionSlotProvided, isIconSlotProvided } from '../search-field.utils';

/**
 * @slot default - default slot for the content of the groupui-search-suggestion
 * @slot start - slot for leading contents like an icon
 * @slot description - slot for descriptive text
 */
@Component({
  tag: 'groupui-search-suggestion',
  styleUrl: 'search-suggestion.scss',
  shadow: true,
})
export class SearchSuggestion {
  /**
   * used to determine what part needs to be highlighted
   */
  @Prop({ reflect: true }) readonly input: string;

  /**
   * makes the highlighting case-insensitive, only usable with sub string highlighting
   */
  @Prop({ reflect: true }) readonly caseInsensitiveHighlighting: boolean;

  /**
   * used to hide the suggestion icon
   */
  @Prop({ reflect: true }) readonly hideIcon: boolean;

  /**
   * icon name e.g. 'clock-24'. Use the matching 24px sized icons. Icon will overwrite the default icon from the search-field for this suggestion.
   */
  @Prop({ reflect: true }) readonly icon: string;

  /**
   * sets a custom icon source e.g. '...path/clock-24.svg', overrides icon property if both are set
   */
  @Prop({ reflect: true }) readonly iconSource: string;

  /**
   * value of the search-suggestion
   */
  @Prop({ reflect: true }) readonly value: string;

  @Element() host: HTMLElement;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  private highlightText() {
    const searchSuggestionText = getDefaultSlotContent(this.host);
    if (this.caseSensitiveCheck(searchSuggestionText) || this.caseInsensitiveCheck(searchSuggestionText)) {
      return (
        <div>
          <b>{searchSuggestionText.substring(0, this.input.length)}</b>
          {searchSuggestionText.substring(this.input.length)}
        </div>
      );
    } else {
      return <div>{searchSuggestionText}</div>;
    }
  }

  private caseSensitiveCheck(text: string) {
    return text?.startsWith(this.input);
  }

  private caseInsensitiveCheck(text: string) {
    return this.caseInsensitiveHighlighting && text?.toLowerCase().startsWith(this.input.toLowerCase());
  }

  private getSuggestionIcon() {
    return this.icon || 'search-24';
  }

  render() {
    return (
      <Host tabIndex={-1} role="option">
        <div class="suggestion">
          {!isIconSlotProvided(this.host) && !this.hideIcon && (
            <groupui-icon name={this.getSuggestionIcon()} src={this.iconSource} />
          )}
          {isIconSlotProvided(this.host) && <slot name="start" />}
          <div class="text">{this.input ? this.highlightText() : <slot></slot>}</div>
          {isDescriptionSlotProvided(this.host) && <slot name="description" />}
        </div>
      </Host>
    );
  }
}
